class Vault {
public:
    Record read(const Subject& who, Id id) const {
        if (!policy_.allows(who, id)) throw AccessDenied(id);   // every path passes here
        return store_.get(id);
    }
private:
    Store store_;                 // no getter, no friend: unreachable from outside
    Policy policy_;
};
// who may even call read() can be narrowed with a passkey token instead of friendship
